export type MutationListener = (
  items: string[],
  done: (error?: Error) => void,
) => void;

export type PipelineComplete = (
  error: Error | null,
  snapshots: readonly (readonly string[])[],
) => void;

export function runMutationListeners(
  source: readonly string[],
  listeners: readonly MutationListener[],
  complete: PipelineComplete,
): void {
  const snapshots: (readonly string[])[] = [];
  const payload = [...source];
  let index = 0;
  let finished = false;

  const finish = (error: Error | null): void => {
    if (finished) return;
    finished = true;
    complete(error, Object.freeze([...snapshots]));
  };

  const advance = (): void => {
    if (finished) return;
    if (index === listeners.length) {
      finish(null);
      return;
    }

    const listener = listeners[index++];
    let acknowledged = false;

    const done = (error?: Error): void => {
      if (acknowledged || finished) return;
      acknowledged = true;
      if (error !== undefined) {
        finish(error);
        return;
      }
      snapshots.push(Object.freeze([...payload]));
      advance();
    };

    try {
      listener(payload, done);
    } catch (value: unknown) {
      if (!acknowledged) {
        acknowledged = true;
        finish(value instanceof Error ? value : new Error(String(value)));
      }
    }
  };

  advance();
}
```

