export interface Broadcast {
  readonly channel: string;
  readonly labels: readonly string[];
}

export type BroadcastListener = (
  message: Broadcast,
  acknowledge: (error?: Error) => void,
) => void;

export class AcknowledgedBroadcaster {
  private readonly listeners: BroadcastListener[] = [];

  subscribe(listener: BroadcastListener): () => void {
    this.listeners.push(listener);
    let active = true;
    return (): void => {
      if (!active) return;
      active = false;
      const index = this.listeners.indexOf(listener);
      if (index >= 0) this.listeners.splice(index, 1);
    };
  }

  publish(
    message: Broadcast,
    complete: (error: Error | null) => void,
  ): void {
    const current = [...this.listeners];
    if (current.length === 0) {
      complete(null);
      return;
    }

    const delivered: Broadcast = {
      channel: message.channel,
      labels: [...message.labels],
    };
    const errors: Array<Error | undefined> = new Array(current.length);
    let remaining = current.length;
    let completed = false;

    const finishOne = (index: number, error?: Error): void => {
      if (error !== undefined) errors[index] = error;
      remaining--;
      if (remaining === 0 && !completed) {
        completed = true;
        complete(errors.find((value): value is Error => value !== undefined) ?? null);
      }
    };

    current.forEach((listener, index) => {
      let acknowledged = false;
      const acknowledge = (error?: Error): void => {
        if (acknowledged) return;
        acknowledged = true;
        finishOne(index, error);
      };

      try {
        listener(delivered, acknowledge);
      } catch (value: unknown) {
        if (!acknowledged) {
          acknowledged = true;
          finishOne(
            index,
            value instanceof Error ? value : new Error(String(value)),
          );
        }
      }
    });
  }
}
```

